package kr.danta.core.nation;
import kr.danta.core.state.GameState;import kr.danta.core.territory.StrategicPoint;import java.util.*;
/** DEV-095 capital-fall -> vassal transition. Does not transfer remaining territory, research or armies. */
public final class VassalService{private final GameState gameState;private final Map<String,VassalRelation> relations=new LinkedHashMap<>();public VassalService(GameState g){gameState=Objects.requireNonNull(g);}public synchronized VassalRelation onCapitalFallen(String defeated,String victor,long runtimeMs){NationState v=requireNation(defeated);requireNation(victor);if(defeated.equals(victor))throw new IllegalArgumentException("vassal and overlord must differ");if(v.status()==NationStatus.VASSAL)throw new IllegalStateException("nation is already vassal");String capital=v.capitalPointId().orElseThrow(()->new IllegalStateException("nation has no designated capital"));StrategicPoint p=gameState.strategicPoint(capital).orElseThrow(()->new IllegalStateException("designated capital point does not exist"));if(p.ownerNationId().filter(victor::equals).isEmpty())throw new IllegalStateException("capital is not controlled by victor");v.setStatus(NationStatus.VASSAL);VassalRelation r=new VassalRelation(defeated,victor,runtimeMs);relations.put(defeated,r);return r;}public synchronized Optional<VassalRelation> relation(String vassal){return Optional.ofNullable(relations.get(vassal));}public synchronized List<VassalRelation> relations(){return List.copyOf(relations.values());}public synchronized void restore(VassalRelation r){requireNation(r.vassalNationId());requireNation(r.overlordNationId());relations.put(r.vassalNationId(),r);gameState.nation(r.vassalNationId()).orElseThrow().setStatus(NationStatus.VASSAL);}public synchronized void clear(){relations.clear();}private NationState requireNation(String id){return gameState.nation(id).orElseThrow(()->new IllegalArgumentException("nation does not exist: "+id));}}
